  whyVsBest: (title, full, po, pb) => `A recomendada, “${title}”, ${full ? 'também enche todos os destinos' : 'não enche todos os destinos'} com ${po} peças no meio. Este balancer usa ${pb}.`,
  whyBalWhen: 'Vale o balancer quando você quer todas as linhas de destino com a mesma taxa, ou quando vai mexer nas máquinas depois e não quer refazer a ligação.',
