  zoomIn: 'Aproximar', zoomOut: 'Afastar', zoomFit: 'Ver tudo', hint2dZoom: 'Ctrl + roda do mouse ou pinça para o zoom, arraste para mover. Passe o mouse ou toque numa peça para ver só o caminho dela.',
  view2dLabel: 'Desenho', view2dScheme: 'Esquema', view2dPlan: 'Planta',
  tipView2d: 'Nos dois, cada esteira sai e entra pelo lado certo da peça, como no jogo: o splitter recebe por trás e solta pela frente e pelos lados, o merger o contrário, e nunca duas no mesmo lado. Esquema: compacto, cabe na tela. Planta: o mesmo desenho em escala, com a grade de fundações, o espaço que ocupa e marcações do tamanho do Blueprint Designer. Passe o mouse ou toque numa peça, entrada ou saída para ver só o caminho dela.',
  lgMixed: 'esteira misturada: cor da saída para onde vai',
  lgGrid: 'fundação (8 m)', lgPieceNum: 'ordem de montagem', lgSplitWays: 'splitter (o número é em quantas saídas ele divide)', lgMergerJoin: 'merger (junta até 3 esteiras numa)',
  thSpace: 'Espaço', spaceVal: (fw, fd) => `${fw}×${fd} fundações`, spaceM: (w, d) => `${w}×${d} m`,
